package main

import (
	"math/big"
	"strings"
	"testing"
	"time"
)

// Reference values below were computed independently with Python's decimal
// module at 1200 significant digits (getcontext().prec = 1200; x ** y, exp(),
// ln(), sqrt()) and are quoted to 331 digits.

// relErr returns |got-want|/|want| at extra precision.
func relErr(got, want *big.Float) *big.Float {
	d := new(big.Float).SetPrec(workPrec+64).Sub(got, want)
	return d.Quo(d, want).Abs(d)
}

// parseRef parses a reference decimal string at extra precision.
func parseRef(t *testing.T, s string) *big.Float {
	t.Helper()
	f, ok := new(big.Float).SetPrec(workPrec + 64).SetString(s)
	if !ok {
		t.Fatalf("bad reference %q", s)
	}
	return f
}

func pow2(e int) *big.Float { return new(big.Float).SetMantExp(big.NewFloat(1), e) }

// TestBigLnExp checks ln and exp against reference constants at the 1088-bit
// working precision: ln to within 2^-1070, exp to within 2^-1060 (its
// argument reduction r - n·ln2 loses up to log2|r| bits; at |r| ~ 2^20 that
// still leaves ~35 bits to spare over the 1024-bit result).
func TestBigLnExp(t *testing.T) {
	onePlus := newWork().Add(newWork().SetInt64(1), pow2(-500))
	tests := []struct {
		name string
		got  *big.Float
		want string
	}{
		{"ln2 constant", ln2, "6.-1"},
		{"ln 2", bigLn(newWork().SetInt64(2)), "6.-1"},
		{"ln 10", bigLn(newWork().SetInt64(10)), "2."},
		{"ln 0.001", bigLn(newWork().Quo(newWork().SetInt64(1), newWork().SetInt64(1000))), "-6."},
		{"ln(1+2^-500)", bigLn(onePlus), "3.-151"},
		{"exp 1", bigExp(newWork().SetInt64(1)), "2."},
		{"exp -20.5", bigExp(newWork().SetFloat64(-20.5)), "1.-9"},
		{"exp 1000000.25", bigExp(newWork().SetFloat64(1000000.25)), "3."},
		{"exp(ln 10)", bigExp(bigLn(newWork().SetInt64(10))), "1e1"},
		{"exp 0", bigExp(newWork()), "1"},
	}
	for _, tt := range tests {
		tol := -1070
		if strings.HasPrefix(tt.name, "exp") {
			tol = -1060
		}
		if e := relErr(tt.got, parseRef(t, tt.want)); e.Cmp(pow2(tol)) > 0 {
			t.Errorf("%s: relative error %s, want <= 2^%d", tt.name, e.Text('g', 3), tol)
		}
	}
	// ln(1) is exactly 0.
	if v := bigLn(newWork().SetInt64(1)); v.Sign() != 0 {
		t.Errorf("ln 1 = %s, want 0", v.Text('g', 10))
	}
}

// TestFractionalPowers checks non-integer powers against the reference to
// within a couple of ulps of the 1024-bit result, and that the printed result
// agrees with the reference to ~299 significant digits.
//
// Decimal literals such as 0.999 are not exact in binary: the parsed value is
// off by up to 2^-1025 relative. base^exp magnifies a base error by |exp| and
// an exponent error by |exp·ln base|, so those cases get a tolerance widened
// by that factor (e.g. 0.999^-123456.5: 123456·2^-1025 ≈ 2^-1008), since no
// evaluator working on the parsed 1024-bit input can do better.
func TestFractionalPowers(t *testing.T) {
	tests := []struct {
		expr string
		want string
		tol  int // allowed relative error is 2^tol
	}{
		{"2^0.5", "1.", -1023},
		{"10^0.3", "1.", -1023},
		{"3^1.7", "6.", -1023},
		{"7.5^(0-2.25)", "1.-2", -1023},
		{"0.5^0.1", "9.-1", -1023},
		{"1.0001^12345.6789", "3.", -1009},
		{"123456789^0.000001", "1.", -1023},
		{"2^1000.5", "1.", -1023},
		{"(10^300)^0.123", "7.", -1015},
		{"(2^-3000)^0.37", "7.-335", -1013},
		{"1.5^(0-0.75)", "7.-1", -1023},
		{"(1+2^-500)^(2^500+0.5)", "2.", -1023},
		{"(0.999)^(0-123456.5)", "4.", -1005},
		{"2^(2^17-0.5)", "2.", -1023},
	}
	for _, tt := range tests {
		t.Run(tt.expr, func(t *testing.T) {
			v, err := evaluate(tt.expr)
			if err != nil {
				t.Fatalf("evaluate: %v", err)
			}
			want := parseRef(t, tt.want)
			if e := relErr(v, want); e.Cmp(pow2(tt.tol)) > 0 {
				t.Errorf("relative error %s (2^%d), want <= 2^%d", e.Text('g', 3), e.MantExp(nil), tt.tol)
			}
			s, err := formatResult(v)
			if err != nil {
				t.Fatalf("formatResult: %v", err)
			}
			// The printed form carries outputDigits significant digits, so
			// it may be off by half a unit in the 300th digit.
			printed := parseRef(t, s)
			if e := relErr(printed, want); e.Cmp(pow2(-990)) > 0 {
				t.Errorf("printed %s\nreference %s\nrelative error %s, want <= 2^-990 (~1e-298)", s, tt.want, e.Text('g', 3))
			}
			if n := len(sigDigits(s)); !v.IsInt() && n > outputDigits {
				t.Errorf("printed %d significant digits, want <= %d", n, outputDigits)
			}
		})
	}
}

// sigDigits returns the significant digits of a decimal string, without
// sign, point, exponent or leading zeros.
func sigDigits(s string) string {
	if i := strings.IndexAny(s, "eE"); i >= 0 {
		s = s[:i]
	}
	s = strings.NewReplacer("-", "", ".", "").Replace(s)
	return strings.TrimLeft(s, "0")
}

// TestFractionalPowersExact checks that fractional powers with short exact
// answers print them, rather than ln/exp rounding noise.
func TestFractionalPowersExact(t *testing.T) {
	tests := []struct {
		expr    string
		want    string
		wantErr error
	}{
		{"4^0.5", "2", nil},
		{"9^0.5", "3", nil},
		{"16^0.25", "2", nil},
		{"8^(1/3)", "2", nil},
		{"27^(1/3)", "3", nil},
		{"1000^(1/3)", "10", nil},
		{"100^1.5", "1000", nil},
		{"0.25^0.5", "0.5", nil},
		{"4^(0-0.5)", "0.5", nil},
		{"2^0.5*2^0.5", "2", nil},
		{"(2^0.5)^2", "2", nil},
		{"(10^400)^0.5", "1" + strings.Repeat("0", 200), nil},
		{"(2^-2000)^0.5*2^1000", "1", nil},
		{"1/3*3", "1", nil},
		{"0.1+0.2", "0.3", nil},
		{"2^0.5", "1.41421356237309504880168872420969807856967187537694807317667973799073247846210703885038753432764157273501384623091229702492483605585073721264412149709993583141322266592750559275579995050115278206057147010955997160597027453459686201472851741864088919860955232923048430871432145083976260362799525140799", nil},
		{"(0-8)^(1/3)", "", errNotReal},
		{"(0-4)^0.5", "", errNotReal},
	}
	for _, tt := range tests {
		t.Run(tt.expr, func(t *testing.T) {
			v, err := evaluate(tt.expr)
			if tt.wantErr != nil {
				if err != tt.wantErr {
					t.Fatalf("err = %v, want %v", err, tt.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("evaluate: %v", err)
			}
			if got := mustFormat(t, v); got != tt.want {
				t.Errorf("%s = %s, want %s", tt.expr, got, tt.want)
			}
		})
	}
}

// TestFractionalPowerIdentities checks b^e · b^-e = 1 and (b^e)^(1/e) = b
// across a grid of bases and exponents.
func TestFractionalPowerIdentities(t *testing.T) {
	bases := []string{"0.001", "0.5", "0.9", "1.1", "2", "3.7", "10", "12345.678", "10^50", "2^-700"}
	exps := []string{"0.5", "0-0.5", "1/3", "2.75", "0-7.1", "0.001", "123.456"}
	one := newBig().SetInt64(1)
	for _, b := range bases {
		for _, e := range exps {
			prod, err := evaluate("(" + b + ")^(" + e + ")*(" + b + ")^(0-(" + e + "))")
			if err != nil {
				t.Errorf("b=%s e=%s: %v", b, e, err)
				continue
			}
			if d := relErr(prod, one); d.Cmp(pow2(-1000)) > 0 {
				t.Errorf("(%s)^(%s)*(%s)^-(%s) is %s off 1", b, e, b, e, d.Text('g', 3))
			}
			back, err := evaluate("((" + b + ")^(" + e + "))^(1/(" + e + "))")
			if err != nil {
				t.Errorf("b=%s e=%s round trip: %v", b, e, err)
				continue
			}
			want, _ := evaluate(b)
			if d := relErr(back, want); d.Cmp(pow2(-990)) > 0 {
				t.Errorf("((%s)^(%s))^(1/(%s)) is %s off %s", b, e, e, d.Text('g', 3), b)
			}
		}
	}
}

// TestFractionalPowerCost bounds the cost of non-integer powers.
func TestFractionalPowerCost(t *testing.T) {
	start := time.Now()
	n := 0
	for _, b := range []string{"2", "0.7", "1.0001", "10^300", "2^-3000", "123456.789"} {
		for _, e := range []string{"0.5", "0-1.25", "1/7", "12.345678", "0.0000001"} {
			if _, err := evaluate("(" + b + ")^(" + e + ")"); err != nil {
				t.Fatalf("(%s)^(%s): %v", b, e, err)
			}
			n++
		}
	}
	if d := time.Since(start); d > time.Second {
		t.Errorf("%d fractional powers took %s", n, d)
	}
}
